<?php $title='Offers';require 'includes/header.php';$offers=$pdo->query("SELECT * FROM offers WHERE active=1 ORDER BY id DESC")->fetchAll();?><section class="page-head"><div class="container"><h1>Offers</h1><p>Current product offers and promotions.</p></div></section><div class="container py-5"><div class="row g-4"><?php foreach($offers as $o):?><div class="col-md-6 col-lg-4"><div class="product-card h-100"><img class="w-100" src="<?=e($o['image']?:'https://images.unsplash.com/photo-1497440001374-f26997328c1b?w=900')?>"><div class="p-4"><h4><?=e($o['title'])?></h4><p><?=e($o['description'])?></p><a href="quote.php" class="btn btn-primary">Get Offer</a></div></div></div><?php endforeach;if(!$offers):?><div class="col-12"><div class="alert alert-info">No active offers currently.</div></div><?php endif;?></div></div><?php require 'includes/footer.php';?>